/* Bolt thief update (moby Bolt Thief, level 14): hit knockback, turn to the hero, walk a path, then fall back. */
void BoltThiefUpdate(L14Moby *m) {
    L14Data *d = m->data;
    char *hit;

    if ((m->status & 2) && m->frame == m->animation && m->frame == 1)
        MobyBlendAnimation(m, 4, 0, scale_ticks(5));
    if (((L14Moby *)g_hero.coll_hit_moby) == m && m->animation != 1 && m->frame != 1)
        MobyBlendAnimation(m, 1, 0, scale_ticks(5));
    hit = MobyGetHitMessage(m, 0x210000, 0);
    if (hit && m->state != 6) {
        Hero *hero = &g_hero;

        d->knock_drag = 0.008f;
        d->knock_gravity = 0.0005f;
        d->knock_speed = g_frame_time * 24.0f;
        d->knock_rise = g_frame_time * 12.0f;
        d->knock_flags = 1;
        d->knock_bAD = 0;
        InitKnockback_v(m, d->knock, 1, 1, 0,
                        fast_atan2(m->position[0] - hero->motion.pos.f[0], m->position[1] - hero->motion.pos.f[1]));
        d->ticks = 0x78;
        SetDeathBits(m, 0, -1);
        m->state = 6;
    }
    m->opacity = 0xFF;
    switch (m->state) {
        case 0:
            if (d->mode == 2) {
                m->state = 1;
                d->turn = 0.0f;
                MobySetAnimation(m, 4, 0);
            } else {
                if (d->path == -1) {
                    STUB_printf(oltanis_bolt_thief_no_path_msg, m->id);
                    DeleteMoby(m);
                    return;
                }
                if (*(int *)l14_paths[d->path] == 0) {
                    STUB_printf(oltanis_bolt_thief_empty_path_msg, m->id);
                    DeleteMoby(m);
                    return;
                }
                if (d->mode != 1) {
                    if (d->other_path == -1) {
                        STUB_printf(oltanis_bolt_thief_no_other_path_msg, m->id);
                        DeleteMoby(m);
                        return;
                    }
                    if (*(int *)l14_paths[d->other_path] == 0) {
                        STUB_printf(oltanis_bolt_thief_empty_other_path_msg, m->id);
                        DeleteMoby(m);
                        return;
                    }
                }
                if (d->trigger == -1) {
                    STUB_printf(oltanis_bolt_thief_no_trigger_msg, m->id);
                    DeleteMoby(m);
                    return;
                }
                initialize_moby_path_state(m);
                m->state = 2;
                m->collision = 0x80;
                m->flags |= 0x41;
                m->bounds = 0;
            }
            d->child = 0;
            break;
        case 1: {
            Hero *hero = &g_hero;

            MobySpringTurn_v((char *)m,
                             fast_atan2(hero->motion.pos.f[0] - m->position[0], hero->motion.pos.f[1] - m->position[1]),
                             &d->turn, 0.005f, 0.2f, 0.0f);
            emit_moby_offset_particles(m);
            break;
        }
        case 2:
            if (is_point_inside_clip_volume(&g_hero.motion.pos, d->trigger)) {
                if (d->mode == 1) {
                    MobySetAnimation(m, 0, 0);
                } else {
                    d->child = spawn_bolt_thief_mine(m, m->position);
                    update_linked_moby_position(m);
                    MobySetAnimation(m, 2, 0);
                }
                m->flags &= 0xFFBE;
                m->bounds = m->model->bounds;
                m->state = 4;
            }
            break;
        case 4:
            if (d->mode == 0)
                update_linked_moby_position(m);
            if (update_bolt_thief_path_movement((char *)m)) {
                m->state = 3;
                MobyBlendAnimation(m, 3, 0, 5);
            }
            emit_moby_offset_particles(m);
            break;
        case 3: {
            L14Data *a = m->data;
            char *path = l14_paths[a->path];
            float target[4];
            float zero;

            if (a->mode == 0)
                update_linked_moby_position(m);
            qcopy(target, path + *(int *)path * 16);
            zero = 0.0f;
            Spring(m->position, &a->vx, target[0], oltanis_bolt_thief_spring_stiffness,
                   oltanis_bolt_thief_spring_damping, zero);
            Spring(m->position + 1, &a->vy, target[1], oltanis_bolt_thief_spring_stiffness,
                   oltanis_bolt_thief_spring_damping, zero);
            Spring(m->position + 2, &a->vz, target[2], oltanis_bolt_thief_spring_stiffness,
                   oltanis_bolt_thief_spring_damping, zero);
            if ((m->status & 2) && m->frame == m->animation) {
                if (a->mode == 1) {
                    m->state = 1;
                    a->turn = zero;
                    MobySetAnimation(m, 4, 0);
                } else {
                    if (a->child) {
                        moby_set_state_one(a->child);
                        a->child = 0;
                    }
                    m->state = 5;
                    MobyBlendAnimation(m, 0, 0, 20);
                    a->timer = zero;
                    a->counter = 0;
                }
            }
            emit_moby_offset_particles(m);
            break;
        }
        case 5:
            if (update_bolt_thief_path_movement((char *)m)) {
                char *path;

                m->state = 2;
                m->bounds = 0;
                m->flags |= 0x41;
                d->timer = 0.0f;
                d->counter = 0;
                d->turn = d->vx = d->vy = d->vz = d->timer;
                path = l14_paths[d->path];
                qcopy(m->position, path + 0x10);
                m->rotation[2] = fast_atan2(*(float *)(path + 0x20) - *(float *)(path + 0x10),
                                            *(float *)(path + 0x24) - *(float *)(path + 0x14));
            } else {
                emit_moby_offset_particles(m);
            }
            break;
        case 6:
            if (step_moby_motion(m, d->knock) & 3) {
                cart_burst(m, m->position, -1, 1.0f, 13.0f);
                DeleteMoby(m);
                return;
            }
            if (m->position[2] < 5.0f) {
                DeleteMoby(m);
                return;
            }
            break;
    }
    StepColorFade(m, d->effect);
}
