/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l14/gameplay/vendor/00300e00.c, FUN_L14_00306b78. */
void StepOnSwitchUpdate(struct Moby *moby) {
    s32 *d = (s32 *)moby->pvars;
    s16 id;
    s32 i;
    s32 list;
    char *p;
    f32 angle;
    s32 color;
    u32 shade;
    u32 high;

    switch (moby->state) {
        case 0:
            *(f32 *)(d + 3) = random_angle_radians();
            moby->pos.z -= 0.35f;
            id = (s16)moby->save_id;
            if (oltanis_collected_flags_base_r2.collected[id] != 0 ||
                (level_moby_killed[g_current_level_index][id >> 5] >> (moby->save_id & 31) & 1) != 0 ||
                (d[2] != 0 && saved_mission_state[moby->mission + g_current_level_index * 16] == 0xFF)) {
                moby->command = 2;
                moby->glow_color = 0x80208020;
                moby->state = 2;
                list = d[0];
                if (list != -1) {
                    i = 0;
                    if (*(s32 *)l14_paths[list] > 0) {
                        do {
                            p = l14_paths[list] + i * 16;
                            if (*(f32 *)(p + 0x1C) == ((f32 *)d)[1])
                                *(s32 *)(p + 0x1C) = 0;
                            list = d[0];
                            i++;
                        } while (i < *(s32 *)l14_paths[list]);
                    }
                }
            } else {
                moby->state = 1;
            }
            break;
        case 1:
            angle = FastAddRots(*(f32 *)(d + 3), g_frame_time * 6.2831855f);
            *(f32 *)(d + 3) = angle;
            color = truncate_float_to_s32((FastSin(angle) * 4.0f - 3.0f) * 128.0f);
            if (color > 0x80)
                color = 0x80;
            else if (color < 0x20)
                color = 0x20;
            shade = 0x80000000 | (color << 8);
            high = color << 16;
            moby->glow_color = high | shade | color;
            if (g_hero_r2.ground_moby == moby && g_hero_r2.air_frames.s == 0) {
                id = (s16)moby->save_id;
                level_moby_killed[g_current_level_index][id >> 5] |= 1 << (moby->save_id & 31);
                oltanis_moby_killed_bits[(s16)moby->save_id >> 5] |= 1 << (moby->save_id & 31);
                moby->state = 2;
                moby->command = 1;
                moby->glow_color = 0x80208020;
                Moby_PlaySound(0, 0, moby);
                list = d[0];
                if (list != -1) {
                    i = 0;
                    if (*(s32 *)l14_paths[list] > 0) {
                        do {
                            p = l14_paths[list] + i * 16;
                            if (*(f32 *)(p + 0x1C) == ((f32 *)d)[1])
                                *(s32 *)(p + 0x1C) = 0;
                            list = d[0];
                            i++;
                        } while (i < *(s32 *)l14_paths[list]);
                    }
                }
            }
            break;
    }
}
