    v[2] = oltanis_path_camera_keys_r[2];
    v[3] = oltanis_path_camera_keys_r[3] * 0.017453292f;
    v[4] = oltanis_path_camera_keys_r[4] * 0.017453292f;
    w = (int *)((char *)cam->saved_state + 0x74);
    *w = 0;
    w[1] = 0;
    w[2] = 0;
    w[3] = 0;
    w[4] = 0;
    f = fast_atan2(g_hero.moby->rot_row1.x, g_hero.moby->rot_row1.y);
    ang[1] = v[1];
    ang[0] = f;
    ang[2] = v[2];
    compute_position_from_spherical_offset(&cam->pos, ang, &g_hero.motion);
    FastVecSub(dir, &g_hero.motion, &cam->pos);
    FastVecScale(up, &g_hero.gravity_dir, -1.5f);
    FastVecAdd(dir, dir, up);
    vec_scale_to_length(&cam->m0, dir, 1.0f);
    FastVecCross(&cam->m1, &cam->m0, up);
    vec_scale_to_length(&cam->m1, &cam->m1, 1.0f);
